import{useEffect,useState}from"react";import{getMyListings}from"../../api/vendorApi";import{Link}from"react-router-dom";export default function ListingStatus({mode}){const[x,setX]=useState([]);useEffect(()=>{getMyListings().then(r=>setX(r.data?.data||[])).catch(()=>setX([]))},[]);const map={pending:["PENDING_APPROVAL","SUBMITTED"],approved:["APPROVED","PUBLISHED"],rejected:["REJECTED"]};const y=x.filter(p=>map[mode].includes(p.status)||map[mode].includes(p.approvalStatus));return <div className="mx-auto max-w-7xl px-4 py-8"><p className="text-sm text-slate-400">VENDOR</p><h1 className="text-3xl font-black">{mode[0].toUpperCase()+mode.slice(1)} listings</h1><div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{y.map(p=><Link className="card p-5" key={p.id} to={`/listing/${p.id}`}><span className="text-xs text-slate-400">{p.type}</span><h2 className="mt-1 font-bold">{p.title}</h2><p className="mt-2 text-sm text-slate-500">{p.status||p.approvalStatus}</p></Link>)}{!y.length&&<div className="card p-10 text-center text-slate-400 sm:col-span-2 lg:col-span-3">No {mode} listings.</div>}</div></div>}
